*/
scwin.ipt_ReportTmp_onkeypress = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_ReportTmp_onkeypress — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        console.warn('[sdd] 미실현(재설계 분류 #128): keyEvent(' + "" + ')');/* sdd-asis-lifecycle:end */

